const availableFields=['MLS','Nursing','Psychology','Pharmacy'];
const programs=window.LEARNIT_PROGRAMS||[];
const fields=availableFields;
const detailedTopics=[
{id:'cell-biology',title:'Cell Biology: Membranes & Transport',field:'Biology',description:'Explore membrane structure and how cells move materials across their boundaries.',keywords:'cell membrane diffusion osmosis active transport',sections:{overview:'The plasma membrane forms a selective boundary around a cell. Its fluid mosaic structure includes a phospholipid bilayer, proteins, cholesterol, and carbohydrates.',history:'The modern membrane model developed through decades of microscopy and biochemical work. Singer and Nicolson proposed the fluid mosaic model in 1972; later work refined the model to account for membrane domains and cytoskeletal interactions.',concepts:'Phospholipids are amphipathic, with hydrophilic heads and hydrophobic tails. Integral and peripheral proteins support transport, signaling, and recognition. Selective permeability depends on molecular size, charge, and lipid solubility.',process:'Simple diffusion moves particles down a concentration gradient. Facilitated diffusion uses membrane proteins without direct energy input. Active transport couples movement to energy, often moving substances against a gradient. Osmosis describes net water movement across a selectively permeable membrane.',significance:'Membrane transport supports nutrient uptake, waste removal, electrical signaling, and maintenance of cellular conditions. Transport mechanisms also inform physiology and pharmacology.',limitations:'Rates vary with temperature, membrane composition, concentration gradients, and transporter availability. Simplified diagrams may imply a static membrane; real membranes are dynamic.',recap:'Membranes are dynamic selective barriers. Passive transport follows gradients; active transport requires an energy source.',sources:[['Molecular Biology of the Cell, 4th edition','Alberts et al.','Garland Science, 2002','https://www.ncbi.nlm.nih.gov/books/NBK21054/'],['The fluid mosaic model of the structure of cell membranes','S. J. Singer and G. L. Nicolson','Science, 1972','https://doi.org/10.1126/science.175.4023.720']] }},
{id:'homeostasis',title:'Homeostasis & Feedback Loops',field:'Anatomy & Physiology',description:'Learn how physiological systems maintain internal conditions within workable ranges.',keywords:'homeostasis feedback negative positive physiology',sections:{overview:'Homeostasis refers to regulation of internal conditions within ranges that support normal function. It is dynamic regulation, not a perfectly fixed state.',history:'The concept developed from early physiological studies of the internal environment. Walter Cannon popularized the term homeostasis in the early twentieth century, building on Claude Bernard’s work.',concepts:'A regulated variable is monitored by sensors. A control center compares information with a reference range, and effectors produce a response. Negative feedback tends to counter a deviation; positive feedback amplifies a process until a specific endpoint.',process:'In a basic negative-feedback loop, a change is detected, information is integrated, and a response reduces the initial deviation. Body temperature and blood glucose are common teaching examples, though real regulation involves interacting pathways.',significance:'Feedback regulation connects organ systems and helps explain physiological responses to exercise, illness, and environmental change.',limitations:'Introductory diagrams simplify overlapping pathways and do not capture all timing, thresholds, or individual variation. A normal range is not a universal fixed value.',recap:'Homeostasis is ongoing regulation. Negative feedback commonly reduces deviations; positive feedback amplifies a process until an endpoint.',sources:[['OpenStax Anatomy and Physiology 2e','OpenStax, Rice University','2022','https://openstax.org/details/books/anatomy-and-physiology-2e'],['The Wisdom of the Body','Walter B. Cannon','W. W. Norton, 1932','https://archive.org/details/wisdomofbody00cann']] }},
{id:'psych-learning',title:'Learning: Classical & Operant Conditioning',field:'Psychology',description:'Compare associative learning, reinforcement, and behavior change.',keywords:'psychology learning conditioning reinforcement behavior',sections:{overview:'Learning is a relatively lasting change in knowledge or behavior associated with experience. Classical and operant conditioning are influential frameworks for studying associative learning.',history:'Ivan Pavlov’s work on conditioned reflexes informed classical conditioning. Edward Thorndike and B. F. Skinner contributed to the study of consequences and operant behavior.',concepts:'In classical conditioning, an organism learns an association between stimuli. In operant conditioning, consequences influence the future likelihood of a behavior. Reinforcement increases behavior; punishment decreases behavior.',process:'Classical conditioning pairs stimuli over time. Operant conditioning involves behavior followed by a consequence. Reinforcement can be positive (adding a stimulus) or negative (removing a stimulus); these terms do not mean good and bad.',significance:'Learning theory informs behavioral research, education, and some therapeutic approaches. Applications should be adapted to context and supported by appropriate evidence.',limitations:'Learning is not fully explained by conditioning alone. Cognition, biology, social context, and individual differences also matter. Findings from one setting may not generalize to another.',recap:'Classical conditioning links stimuli. Operant conditioning links behavior and consequences. Reinforcement increases behavior; punishment decreases it.',sources:[['About Behaviorism','B. F. Skinner','Knopf, 1974','https://archive.org/details/aboutbehavioris00skin'],['Psychology 2e','OpenStax','2020','https://openstax.org/details/books/psychology-2e']] }},
{id:'microbiology',title:'Bacterial Growth & Culture',field:'Medical Technology (Medical Laboratory Science)',description:'Review growth phases, culture conditions, and interpretation limits.',keywords:'bacteria microbiology laboratory culture growth phases',sections:{overview:'Bacterial growth in a closed culture is often described in phases: lag, exponential, stationary, and death. These phases describe a population under particular conditions.',history:'Microbial culture methods became central to microbiology through nineteenth-century advances in sterilization, media, and laboratory technique, including work by Robert Koch and others.',concepts:'Growth depends on nutrients, temperature, pH, oxygen availability, and other conditions. A colony-forming unit is an operational estimate of viable, culturable organisms, not necessarily a count of individual cells.',process:'During lag phase, cells adapt to conditions. Exponential phase features rapid division. Nutrient limitation and waste accumulation can lead to stationary phase and later decline. Different organisms require different media and incubation conditions.',significance:'Culture supports organism recovery and identification in research and diagnostic workflows. Interpretation must follow validated laboratory methods and clinical context.',limitations:'Culture may miss organisms that are nonculturable under chosen conditions or suppressed by prior treatment. Contamination, sampling, transport, and incubation can affect results.',recap:'Growth phases describe populations under specific conditions. Culture findings depend on sample quality, method, and organism requirements.',sources:[['Brock Biology of Microorganisms, 16th edition','Madigan et al.','Pearson, 2021','https://www.pearson.com/en-us/subject-catalog/p/brock-biology-of-microorganisms/P200000003247/9780134874401'],['Bacteriological Analytical Manual','U.S. Food and Drug Administration','Ongoing','https://www.fda.gov/food/laboratory-methods-food/bacteriological-analytical-manual-bam']] }},
{id:'pharmacokinetics',title:'Pharmacokinetics: ADME',field:'Pharmacology',description:'Understand absorption, distribution, metabolism, and excretion as a framework.',keywords:'pharmacology pharmacokinetics ADME absorption distribution metabolism excretion',sections:{overview:'Pharmacokinetics describes how drug concentration changes in the body over time. ADME organizes the processes of absorption, distribution, metabolism, and excretion.',history:'Quantitative pharmacokinetics developed alongside advances in physiology, analytical chemistry, and drug development. Models now range from simple compartment approaches to physiologically based models.',concepts:'Bioavailability describes the fraction of an administered dose reaching systemic circulation unchanged. Clearance relates drug elimination rate to concentration. Half-life depends on distribution volume and clearance in simplified linear models.',process:'Absorption moves drug into systemic circulation; distribution describes reversible movement between blood and tissues; metabolism chemically transforms compounds; excretion removes drug or metabolites. These processes can occur in parallel.',significance:'ADME concepts inform dose design and interpretation of concentration-time profiles. Individual factors and interactions can change exposure; clinical dosing should rely on approved prescribing information and professional judgment.',limitations:'Simple models may not describe nonlinear kinetics, active metabolites, tissue compartments, or time-varying physiology. A half-life alone does not determine an appropriate dose.',recap:'ADME is a useful map of drug handling. Exposure depends on interconnected processes and patient-specific factors.',sources:[['Goodman & Gilman’s The Pharmacological Basis of Therapeutics, 14th edition','Brunton, Hilal-Dandan, and Knoll, eds.','McGraw Hill, 2022','https://accesspharmacy.mhmedical.com/book.aspx?bookID=3097'],['Clinical Pharmacology','U.S. Food and Drug Administration','Ongoing','https://www.fda.gov/drugs/development-resources/clinical-pharmacology']] }},
{id:'blood-pressure',title:'Blood Pressure Measurement Basics',field:'Nursing',description:'Review measurement principles, technique factors, and sources of error.',keywords:'nursing blood pressure measurement cuff hypertension vital signs',sections:{overview:'Blood pressure is the force exerted by circulating blood on arterial walls, commonly reported as systolic over diastolic pressure. A reading is an estimate taken under defined conditions.',history:'The development of cuff-based methods followed early physiological work and improvements in indirect measurement. Korotkoff described sounds used in auscultatory measurement in 1905.',concepts:'Systolic pressure reflects peak arterial pressure during ventricular contraction; diastolic pressure reflects pressure during relaxation. Measurement can be auscultatory or automated.',process:'Accurate measurement depends on appropriate cuff size, positioning, rest, and validated equipment. Follow current professional guidance and local protocols for technique and interpretation.',significance:'Blood pressure measurements contribute to assessment and longitudinal monitoring. Clinical decisions should consider repeated measurements, symptoms, context, and current guidelines.',limitations:'Cuff size, arm position, recent activity, conversation, device validation, arrhythmia, and observer technique can affect readings. One measurement may not represent usual blood pressure.',recap:'Blood pressure readings depend on technique and context. Use validated methods and interpret measurements within clinical guidance.',sources:[['Measurement of Blood Pressure in Humans: A Scientific Statement From the American Heart Association','Muntner et al.','Hypertension, 2019','https://doi.org/10.1161/HYP.0000000000000087'],['Blood Pressure Measurement','American Heart Association','Ongoing','https://www.heart.org/en/health-topics/high-blood-pressure/understanding-blood-pressure-readings/monitoring-your-blood-pressure-at-home']] }},
{id:'biochem-enzymes',title:'Enzyme Kinetics & Inhibition',field:'Biochemistry',description:'Connect enzyme rates with substrate concentration and inhibitor effects.',keywords:'biochemistry enzymes michaelis menten kinetics inhibition',sections:{overview:'Enzymes catalyze reactions by lowering activation energy. Kinetic models describe how reaction rate changes with conditions such as substrate concentration.',history:'The Michaelis–Menten model, published in 1913, offered a mathematical description of enzyme action. Later models expanded kinetic analysis for more complex mechanisms.',concepts:'In the Michaelis–Menten model, Vmax is the limiting rate at high substrate concentration, and Km is the substrate concentration at half Vmax under model assumptions. Competitive inhibition changes apparent Km in the simple model; pure noncompetitive inhibition changes apparent Vmax.',process:'Initial reaction rates are measured across substrate concentrations, then fitted to an appropriate model. Inhibitor effects depend on binding mechanisms and assay conditions.',significance:'Enzyme kinetics helps explain metabolism, laboratory assays, and mechanisms of some drugs. Experimental context is essential when interpreting fitted parameters.',limitations:'Michaelis–Menten assumptions may not hold for cooperative enzymes, multiple substrates, substrate inhibition, or non-steady-state assays. Different inhibition mechanisms can produce similar patterns.',recap:'Kinetic parameters summarize a model under specified conditions. Interpret them alongside assay design and mechanism.',sources:[['Biochemistry, 5th edition','Jeremy M. Berg et al.','W. H. Freeman, 2002','https://www.ncbi.nlm.nih.gov/books/NBK21154/'],['Enzyme kinetics and inhibition','NCBI Bookshelf, Assay Guidance Manual','Updated periodically','https://www.ncbi.nlm.nih.gov/books/NBK92001/']] }},
{id:'public-health',title:'Epidemiology: Incidence & Prevalence',field:'Public Health',description:'Distinguish measures of new cases and existing cases in populations.',keywords:'public health epidemiology incidence prevalence population',sections:{overview:'Incidence and prevalence describe different aspects of disease frequency in a population. They require clear definitions of cases, population, and time.',history:'Population-based study of disease expanded substantially during the nineteenth and twentieth centuries, as vital statistics, surveillance, and analytic epidemiology developed.',concepts:'Incidence counts new cases over a defined period among people at risk. Prevalence counts existing cases in a population at a point or during a period. Prevalence is influenced by both incidence and duration.',process:'Choose a case definition, population denominator, and time window before calculating a measure. Report units and methods clearly; distinguish cumulative incidence from an incidence rate.',significance:'These measures support surveillance, service planning, and research. They answer different questions and should not be treated as interchangeable.',limitations:'Ascertainment, diagnostic access, migration, and case definitions affect estimates. Comparisons can mislead if populations or time periods differ.',recap:'Incidence describes new cases; prevalence describes existing cases. State the denominator and time period.',sources:[['Principles of Epidemiology in Public Health Practice, 3rd edition','Centers for Disease Control and Prevention','2012','https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson3/section2.html'],['Epidemiology, 6th edition','Leon Gordis','Elsevier, 2019','https://www.elsevier.com/books/gordis-epidemiology/celentano/978-0-323-55229-5']] }},
{id:'immune-response',title:'Innate & Adaptive Immunity',field:'Microbiology',description:'Compare rapid innate defenses with antigen-specific adaptive responses.',keywords:'immunity innate adaptive immunology antibodies cells',sections:{overview:'The immune system includes coordinated mechanisms that detect and respond to infection and other challenges. Innate and adaptive immunity are interacting parts of this system.',history:'Immunology grew from observations of protection after infection and vaccination, including work by Edward Jenner and later advances in cellular and molecular biology.',concepts:'Innate immunity provides rapid responses using barriers, cells, and soluble mediators. Adaptive immunity uses antigen-specific lymphocytes and can produce immunological memory.',process:'Innate sensing can activate inflammation and help initiate adaptive responses. B cells can produce antibodies; T cells have several roles, including coordination and killing infected cells.',significance:'Immune principles inform vaccination, infection research, and laboratory testing. Clinical interpretation depends on the test, timing, and patient context.',limitations:'This overview simplifies diverse pathways and exceptions. Immune responses vary with age, genetics, prior exposures, health status, and pathogen.',recap:'Innate and adaptive immunity work together. Innate responses are rapid; adaptive responses are antigen-specific and can form memory.',sources:[['Janeway’s Immunobiology, 9th edition','Murphy and Weaver','Garland Science, 2016','https://www.ncbi.nlm.nih.gov/books/NBK10757/'],['The Immune System','National Institute of Allergy and Infectious Diseases','Ongoing','https://www.niaid.nih.gov/research/immune-system-overview']] }},
{id:'research-design',title:'Research Design & Bias',field:'Psychology',description:'Recognize design choices and biases that affect study interpretation.',keywords:'psychology research design bias confounding study methods',sections:{overview:'Research design is the plan used to answer a question with data. Bias is a systematic error that can distort estimates or conclusions.',history:'Experimental and observational methods developed across the natural and social sciences. Modern research methods emphasize transparent designs, measurement, and replication.',concepts:'Randomization can help balance known and unknown confounders in expectation. Selection bias and measurement bias can arise at different stages. Correlation alone does not establish causation.',process:'Define a question and population, choose appropriate measures, anticipate confounders, and specify analysis before examining results when feasible. Report limitations and uncertainty.',significance:'Critical appraisal helps students interpret behavioral, clinical, and public-health research without overstating what a design can show.',limitations:'No design eliminates every source of bias. Randomized trials may have limited generalizability; observational studies may address questions not feasible to randomize.',recap:'Ask how participants were selected, measured, compared, and analyzed. Match conclusions to the study design.',sources:[['Understanding Clinical Research, 3rd edition','S. B. Hulley et al.','Wolters Kluwer, 2007','https://shop.lww.com/Designing-Clinical-Research/p/9781608318049'],['Users’ Guides to the Medical Literature','JAMA Network','Ongoing','https://jamanetwork.com/collections/6256/users-guides-to-the-medical-literature']] }}
];
const topics=detailedTopics.filter(topic=>availableFields.includes(topic.field)||topic.field==='Medical Technology (Medical Laboratory Science)').map(topic=>topic.field==='Medical Technology (Medical Laboratory Science)'?{...topic,field:'MLS'}:topic);
const curriculumSuggestions=programs.flatMap(program=>program.topics.map(([title,description])=>({field:program.field,title,description,query:title,keywords:`${program.field} ${title} ${description}`})));
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const get=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}};
const getSessionValue=k=>{try{return sessionStorage.getItem(k)}catch{return null}};
