  const card=object({front:string,back:string},['front','back']);
  const topic=object({topic:string,reason:string},['topic','reason']);
  const question=object({question:string,options:{type:'array',items:string,minItems:4,maxItems:4},answer:{type:'integer',minimum:0,maximum:3},explanation:string},['question','options','answer','explanation']);
  const schema=object({reviewer:string,plainLanguage:string,missingTopics:{type:'array',items:topic},flashcards:{type:'array',items:card,minItems:flashcardCount,maxItems:flashcardCount},hardQuiz:{type:'array',items:question,minItems:quizCount,maxItems:quizCount}},['reviewer','plainLanguage','missingTopics','flashcards','hardQuiz']);
