function repairInvalidJsonEscapes(jsonText){let repaired='',insideString=false;for(let i=0;i<jsonText.length;i++){const character=jsonText[i];if(!insideString){if(character==='"')insideString=true;repaired+=character;continue}if(character==='"'){insideString=false;repaired+=character;continue}if(character==='\\'){const next=jsonText[i+1]||'';if('"\\/bfnrt'.includes(next)){repaired+=character+next;i++;continue}if(next==='u'&&/^[0-9a-f]{4}$/i.test(jsonText.slice(i+2,i+6))){repaired+=jsonText.slice(i,i+6);i+=5;continue}repaired+='\\\\';continue}repaired+=character}return repaired}
function parseStudyBundle(raw,requestedCount,requestedQuizCount,previousCards=[],allowedTopics=[]){
  const clean=String(raw).replace(/^\s*\x60\x60\x60(?:json)?/i,'').replace(/\x60\x60\x60\s*$/,'').trim(),start=clean.indexOf('{'),end=clean.lastIndexOf('}');
  if(start<0||end<0)throw Error('Lumi’s response was not in the expected bundle format. Try again.');
  const jsonText=clean.slice(start,end+1);let bundle;try{bundle=JSON.parse(jsonText)}catch{try{bundle=JSON.parse(repairInvalidJsonEscapes(jsonText))}catch{throw Error('Lumi returned malformed JSON. Regenerate the bundle; your uploaded file is still available.')}}
  const reviewer=String(bundle.reviewer||'').trim(),plainLanguage=String(bundle.plainLanguage||'').trim();
  const cards=Array.isArray(bundle.flashcards)?bundle.flashcards.filter(card=>card&&typeof card==='object').map(card=>({front:String(card.front||'').trim(),back:String(card.back||'').trim()})).filter(card=>card.front&&card.back.length>=25):[];
  const previous=new Set(previousCards.map(card=>String(card.front||'').toLowerCase().replace(/\s+/g,' ').trim())),unique=[],seen=new Set(previous);
  for(const card of cards){const key=card.front.toLowerCase().replace(/\s+/g,' ').trim();if(!seen.has(key)){seen.add(key);unique.push(card)}}
  const allowed=new Set(allowedTopics),topicFields=new Map(programs.flatMap(program=>program.topics.map(topic=>[topic[0],program.field])));
  const missingTopics=(Array.isArray(bundle.missingTopics)?bundle.missingTopics:[]).filter(item=>item&&typeof item==='object').map(item=>({topic:String(item.topic||'').trim(),reason:String(item.reason||'').trim()})).filter(item=>item.topic&&allowed.has(item.topic)).map(item=>({...item,field:topicFields.get(item.topic)||''})).slice(0,12);
  const candidates=Array.isArray(bundle.hardQuiz)?bundle.hardQuiz.filter(item=>item&&typeof item==='object').map(item=>({question:String(item.question||'').trim(),options:Array.isArray(item.options)?item.options.map(option=>String(option).trim()):[],answer:Number(item.answer),explanation:String(item.explanation||'').trim()})).filter(item=>item.question&&item.options.length===4&&new Set(item.options.map(option=>option.toLowerCase())).size===4&&Number.isInteger(item.answer)&&item.answer>=0&&item.answer<4&&item.options.every(Boolean)&&item.explanation.length>=35):[];
  const hardQuiz=[],quizSeen=new Set();for(const item of candidates){const key=item.question.toLowerCase().replace(/\s+/g,' ').trim();if(!quizSeen.has(key)){quizSeen.add(key);hardQuiz.push(item)}}
  if(reviewer.length<450||plainLanguage.length<100)throw Error('Lumi returned an incomplete reviewer. Try again so it can explain the material in enough detail.');
  if(unique.length<requestedCount)throw Error('Lumi did not return '+requestedCount+' distinct flashcards with explanatory answers. Try creating the study bundle again.');
  if(hardQuiz.length<requestedQuizCount)throw Error('Lumi could not create the full '+requestedQuizCount+'-question hard quiz with distinct questions and explanations. Try generating the study bundle again.');
  return{reviewer,plainLanguage,missingTopics,flashcards:unique.slice(0,requestedCount),hardQuiz:hardQuiz.slice(0,requestedQuizCount)}
}
let cardAnswerMode='typed';
function shuffleFlashcards(items){const shuffled=items.slice();for(let index=shuffled.length-1;index>0;index--){const other=Math.floor(Math.random()*(index+1));[shuffled[index],shuffled[other]]=[shuffled[other],shuffled[index]]}return shuffled}
function flashcardChoices(card){const expected=String(card.back||'').trim(),normalize=text=>String(text).replace(/\s+/g,' ').trim().toLowerCase(),seen=new Set([normalize(expected)]),distractors=[];currentCards.forEach(candidate=>{if(candidate===card)return;const text=String(candidate.back||'').trim(),key=normalize(text);if(text&&key&&!seen.has(key)){seen.add(key);distractors.push({text,correct:false})}});return shuffleFlashcards([{text:expected,correct:true},...shuffleFlashcards(distractors).slice(0,3)])}
