function splitStudyText(text,maxChars=32000){
  const source=String(text||'').replace(/\r\n?/g,'\n').trim(),chunks=[];let start=0;
  while(start<source.length){
    let end=Math.min(start+maxChars,source.length);
    if(end<source.length){
      for(const separator of ['\n\n','\n','. ']){
        const boundary=source.lastIndexOf(separator,end);
        if(boundary>start+maxChars*.65){end=boundary+separator.length;break}
      }
    }
    if(end<=start)end=Math.min(start+maxChars,source.length);
    chunks.push(source.slice(start,end).trim());start=end;
  }
  return chunks.filter(Boolean);
}
async function prepareStudyBundleSource(text){
  const chunks=splitStudyText(text);
  if(chunks.length===1)return {text:text,chunks:1};
  const notes=[];
  for(let index=0;index<chunks.length;index++){
    $('#fileStatus').textContent='Lumi is reviewing section '+(index+1)+' of '+chunks.length+'…';
    const note=await askAI('sourceNotes',chunks[index],'This is consecutive section '+(index+1)+' of '+chunks.length+' from one uploaded course document. Make a faithful, well-organized set of notes for this section only. Preserve useful source headings, distinctions, examples, values, and references; do not imply you have seen the other sections.');
    notes.push('SECTION '+(index+1)+' OF '+chunks.length+'\n'+note.trim());
  }
  return {text:notes.join('\n\n'),chunks:chunks.length};
}
